begin;
create or replace function public.authorize_apf_dossier_export(p_dossier_id uuid) returns void language plpgsql stable security definer set search_path=public,pg_temp as $$begin perform public.apf_assert_dossier_permission(p_dossier_id,'apf.dossier.export');end $$;
create or replace function public.authorize_apf_batch_export(p_batch_id uuid) returns void language plpgsql stable security definer set search_path=public,pg_temp as $$declare oid uuid;begin select organization_id into oid from public.apf_measurement_batches where id=p_batch_id;if oid is null or not public.has_apf_dossier_permission(oid,'apf.dossier.export',auth.uid())then raise exception'Permissão APF insuficiente: apf.dossier.export'using errcode='42501';end if;end $$;
do $$declare t text;begin foreach t in array array['apf_counting_metric_reviews','apf_logical_file_reviews','apf_exception_reviews','apf_audit_findings','apf_traceability_suggestions','apf_evidence_quality_assessments']loop if to_regclass('public.'||t)is not null then execute format('drop trigger if exists apf_permission_guard on public.%I',t);execute format('create trigger apf_permission_guard before insert or update or delete on public.%I for each row execute function public.apf_enforce_record_permission()',t);end if;end loop;end $$;
revoke all on function public.authorize_apf_dossier_export(uuid)from public,anon;revoke all on function public.authorize_apf_batch_export(uuid)from public,anon;
grant execute on function public.authorize_apf_dossier_export(uuid)to authenticated,service_role;grant execute on function public.authorize_apf_batch_export(uuid)to authenticated,service_role;
commit;
